@startuml

class Faculty {
  + name : string
  + type : string
}

class Student {
  + studentID : int
  + dateOfBirth : date
  + cityOfBirth : string
  + regionOfBirth : string
  + yearOfEnrollment : int
}

class Professor {
  + name : string
  + dateOfBirth : date
  + cityOfBirth : string
}

class Course {
  + code : int
  + lectureHours : int
}

class Exam {
  + grade : string
}

Faculty "1" -- "1..*" Student : enrolledIn
Faculty "1" -- "*" Course : belongsTo
Professor "1" -- "*" Course : teaches
Student "1" -- "*" Exam : passes
Course "1" -- "*" Exam : for
Exam "1" -- "1" Student : takenBy

@enduml

